(function(){const t=document.getElementById("toc-toggle"),e=document.getElementById("toc-sidebar");if(!t||!e)return;t.addEventListener("click",()=>{const n=e.classList.toggle("is-open");t.setAttribute("aria-expanded",n?"true":"false"),e.setAttribute("aria-hidden",n?"false":"true")}),document.addEventListener("keydown",n=>{n.key==="Escape"&&(e.classList.remove("is-open"),t.setAttribute("aria-expanded","false"),e.setAttribute("aria-hidden","true"))})})()